# -*- coding: utf-8 -*-
"""Pend part B: reliance, independence, pensions and everyday spending."""
from author_batch200_vid_74a import E,S,K,O,H
D=H+[['拉丁 de- + pendere → dependere','从某物垂下 → 依靠、取决于'],['古法语 dependre／拉丁借入 → 英语 depend','依靠；由另一条件决定']]
DA=H+[['拉丁 dependere 的分词 dependens；法语 dependant','依附、依赖的'],['英语 dependent／名词也拼 dependant','需要依靠的；受供养的人']]
I=DA+[['英语 in-“不”+ dependent → independent','不依赖、能自主；法语也有相应形式']]
P=[['拉丁 pendere；分词词干 pens-','称量、支付'],['拉丁 pensio／pensionem → 古法语 pension','支付、定期付款'],['中古英语 pensioun → pension','津贴、定期给付；后常用于退休金']]
SP=[['拉丁 expendere／dispendere','称出并支付、花出'],['中世纪拉丁短化 spendere → 古英语 -spendan','支付、用掉；远源可有不同路线分析'],['中古英语 spenden → spend','也可能与古法语 despendre 合流；后泛指花时间、精力']]
W=[
E('depend','英、美 /dɪˈpend/','取决于；依赖；信赖','像挂在支点上的东西：能不能继续，要看支点是否支持它。事情也是如此，结果可能要看天气、钱或另一个人。','de- 是从、向下，与拉丁 pendere 形成 dependere“从……挂下来”，经法语或直接拉丁来源进入英语。现代最常见的是抽象依赖、取决于。',D,'depend on 有两个常见方向：The trip depends on the weather 是行程由天气决定；You can depend on her 是你能信赖她。That depends 意为“那得看情况”。','depend on／upon；depend on someone to do something；depending on the weather；That depends.。','rely on 更突出实际依靠或信任；depend on 也很自然地说结果与条件的关系。通常不能省掉 on 直接接名词。',('Our departure time depends on the weather.','我们的出发时间取决于天气。'),('You can depend on Mei to finish the job carefully.','你可以信赖小梅，她会认真完成这项工作。'),sources=[S('depend'),K('depend'),O('depend')]),
E('dependent','英、美 /dɪˈpendənt/','依赖的；取决于……的；受供养的人','自己还不能完全支撑自己，或某个结果必须跟着另一个条件走。','接法语 dependant、拉丁 dependens／dependent- 的分词形容词路线，不是必须先有英语 depend 再加 -ent。名词的英式拼法常是 dependant，美式通常也用 dependent。',DA,'be dependent on imports 是依赖进口；a dependent child 是经济上需要供养的孩子。数学里的 dependent variable 是因变量，也沿用“值取决于其他量”的关系。','dependent on；financially dependent；dependent children；a dependent variable。','dependable 是别人可以依靠的，dependent 是自己需要依靠的：一个人可以同时对某些资源 dependent，又在工作中很 dependable。',('The island is dependent on imported fuel.','这座岛依赖进口燃料。'),('The form asks how many dependents live with the applicant.','表格询问有多少受供养者与申请人同住。'),sources=[S('dependent'),K('dependent'),O('dependent')]),
E('dependence','英、美 /dɪˈpendəns/','依赖；依靠；取决关系','把“离不开某种支持”当作一种关系来谈，而不是只讲一次求助。','经法语 dépendance，并有中世纪拉丁 dependentia 的来源背景，远接 dependere。英语早期 dependance 与 dependence 并存，后来拉丁化拼写占优势。',H+[['拉丁 dependere → dependentia；法语 dépendance','依赖关系的名词形式'],['英语 dependence','从另一事物获得支持或由其决定的状态']],'dependence on public transport 是生活依赖公共交通；dependence on one supplier 是业务过度或单纯倚靠一家供应商。程度和好坏需要上下文，依赖本身不总是缺点。','dependence on；reduce dependence；economic dependence；mutual dependence。','dependence 与 dependency 有重叠；dependence 多指抽象状态，dependency 在软件里还能指一个具体依赖项。',('Better bus services could reduce our dependence on cars.','更好的公交服务可以减少我们对汽车的依赖。'),('The report highlights the company’s dependence on a single customer.','报告强调了这家公司对单一客户的依赖。'),sources=[S('dependence'),K('dependence'),O('dependence')]),
E('dependency','英、美 /dɪˈpendənsi/','依赖；依赖关系；依赖项；属地','要让 A 运作，先得有 B：B 就可能是 A 的一个依赖项。这比笼统说“依赖”更容易数出具体的连接。','英语依 dependent 配出 -cy 名词，早期有受法语拼写影响的 dependancy；现代 dependency 成为常见形式。其软件义是后来的应用，不是古拉丁专门术语。',DA+[['英语 dependent → dependency','依赖状态；进一步指依赖的事物或附属地区'],['现代技术用法','完成任务或运行程序所需的前提、组件']],'软件说 install the dependencies，是安装程序需要的组件。项目说 a task dependency，是任务之间的先后或前提关系。历史、地理语境的 a dependency 则可指受另一国管辖的属地。','software dependencies；a dependency on；a task dependency；resolve a dependency。','dependence 常说依赖这种状态；dependency 也能数成 one dependency、several dependencies。别把所有 dependency 都译成成瘾。',('The application cannot start because a required dependency is missing.','应用无法启动，因为缺少一个必要的依赖组件。'),('The project plan shows the dependencies between tasks.','项目计划展示了任务之间的依赖关系。'),sources=[S('dependency'),K('dependency'),O('dependency')]),
E('dependable','英、美 /dɪˈpendəbəl/','可靠的；值得依赖的','你把事情交给它或他，通常不用担心关键时刻掉链子。','英语 depend + -able，意思是“可以依靠的”。这里 -able 表示值得或能够被依靠，不是“容易产生依赖”。',D+[['英语 depend + -able → dependable','能够被信赖的']],'a dependable colleague 做事稳妥；a dependable car 平时运作可靠。它强调持续、稳定地履行作用，不一定表示最耀眼或性能最强。','a dependable colleague；dependable transport；a dependable source；highly dependable。','dependent 是需要别人支持，dependable 是能给别人可靠支持。reliable 与 dependable 很接近。',('We need a dependable person to open the shop each morning.','我们需要一个可靠的人每天早上开店。'),('The old car is slow but dependable.','这辆旧车跑得慢，但很可靠。'),sources=[S('dependable'),K('dependable'),O('dependable')]),
E('dependably','英、美 /dɪˈpendəbli/','可靠地；稳定地','一次好还不够，而是反复表现都让人放心：每次需要时，它基本都能稳妥完成。','英语 dependable + -ly，-able 的末尾 e 在拼写中去掉，形成 -ably。副词描写表现方式。',D+[['英语 depend → dependable → dependably','可以依靠的 → 以可靠方式']],'works dependably 是运作稳定；dependably good 是一贯不错。它可以修饰动作，也可修饰形容词，强调可预期的可靠表现。','perform dependably；work dependably；dependably good；deliver dependably。','occasionally brilliantly 是偶尔非常出彩；dependably well 是稳定地做好。它们评价的是不同方面。',('The pump has worked dependably through several winters.','这台泵经历了几个冬天，始终运转可靠。'),('The café serves dependably good coffee.','这家咖啡馆的咖啡一贯不错。'),sources=[S('dependable'),K('dependably'),'https://dictionary.cambridge.org/us/dictionary/english/dependably']),
E('dependability','英、美 /dɪˌpendəˈbɪləti/','可靠性；可依赖的程度','评价一个人或工具时，问的是“关键时刻能不能靠得住”，把这个特点当成一种品质。','英语 dependable 配成 -ability 名词；可理解为 dependable 的可靠性质。重音移到 /ˈbɪl/，不要照 dependable 的原重音一读到底。',D+[['英语 dependable → dependability','可靠的 → 可靠性']],'设备的 dependability 可以体现在很少出故障，人的 dependability 可以体现在守时、兑现承诺。具体衡量方式由场景决定，不是一个固定的单一数值。','a reputation for dependability；value dependability；test dependability。','dependence 是需要依靠的状态；dependability 是值得别人依靠的性质，方向不同。',('Her dependability mattered more to the team than her job title.','对团队来说，她的可靠比她的职位头衔更重要。'),('The company built its reputation on the dependability of its equipment.','这家公司凭设备的可靠性建立了声誉。'),sources=[K('dependability'),S('dependable'),O('dependability')]),
E('independent','英、美 /ˌɪndɪˈpendənt/','独立的；自主的；不受相关一方控制的；无党派人士','自己站得住，或者能作判断而不受某个外部控制者牵着走。独立总要看“相对于谁、在哪方面”。','in-“不”+ dependent，英语近代形成的否定形容词；法语 indépendant 等有平行形式。in- 不是“进入”，所以不是“向里依赖”。',I,'financially independent 是经济独立；an independent review 是由与被审查方有适当独立性的一方作评估。独立不等于永远不合作，也不保证每个判断必定正确。','independent of；an independent company；independent research；an independent candidate。','alone 是独自一个人；independent 是自主、不依赖或不受控制。有人相伴仍可以 independent，独处也不一定自主。',('She wants to become financially independent.','她想在经济上独立。'),('An independent team reviewed the findings.','一个独立团队复核了这些发现。'),sources=[S('independent'),K('independent'),O('independent')]),
E('independence','英、美 /ˌɪndɪˈpendəns/','独立；自主；自立','把“能自己作决定、支撑生活或不受外部统治”的状态当成一件重要的事。','现代对应 independent 的名词，也可分析为 in- + dependence；来源资料有英语配词与法语 indépendance 借入两种描述。保留这些平行分析，不假设法语名词由英语词倒造。',[['拉丁 dependere 家族 → 法语、英语的依赖词汇','依附、依赖及其状态'],['法语 indépendance／英语 independent 与 dependence 的否定名词构词','不依赖、不受控制'],['英语 independence','个人自主、机构独立或政治独立']],'personal independence 是个人自主；editorial independence 是编辑独立；national independence 是国家独立。它们共同点是决定权或支撑能力，但衡量的具体方面不同。','gain independence；maintain independence；financial independence；independence from。','freedom 范围很广，可指行动自由；independence 尤其强调不依赖某方或不受其控制。',('Learning to travel alone gave him a new sense of independence.','学会独自出行，让他有了新的自主感。'),('The newspaper promised to protect its editorial independence.','这家报纸承诺维护编辑独立。'),sources=[S('independence'),K('independence'),O('independence')]),
E('independently','英、美 /ˌɪndɪˈpendəntli/','独立地；自行地；分别地、彼此不依赖地','不用别人一步步带着做，或几个团队各走各的路线，分别得出结果。','英语 independent + -ly。副词既可说自主完成，也可说多个过程没有彼此依赖。',I+[['英语 independent + -ly → independently','以自主或互不依赖的方式']],'work independently 可以是自行工作；independently confirmed 表示有独立途径复核。它不一定等于独处：你可以在人很多的办公室里独立完成任务。','work independently；live independently；independently of；independently verify。','separately 强调分开；independently 强调没有依赖或控制关系。两个人分开办公，仍可能彼此依赖。',('Students are expected to complete the final task independently.','学生应独立完成最后一项任务。'),('Two laboratories independently reached the same conclusion.','两家实验室各自独立得出了相同结论。'),sources=[K('independently'),S('independent'),O('independently')]),
E('pension','养老金义英、美 /ˈpenʃən/；旅馆义英 /ˈpɒ̃sjɒ̃/，美常读 /pɑːnˈsjoʊn/','养老金；退休金；〔欧洲旅游语境〕小旅馆、寄宿旅店','最常见的是人在退休后领取的生活收入。较老的核心是“定期支付一笔钱”，住宿义也从付膳宿费发展出来。','经古法语 pension，接拉丁 pensio／pensionem“付款”，来自 pendere“称量、支付”的 pens- 词干。欧洲旅馆义是后来从法语另借的相关用法，读音也可能保留法语色彩。',[['拉丁 pendere → pensio／pensionem','称量、支付 → 定期付款'],['法语 pension 的两条相关义路','定期给付；膳宿费 → 提供食宿的旅店'],['先后借入英语的两种用法','中古英语养老金、给付路线；后来另借小旅馆义']],'receive a pension 是领养老金；a pension scheme 是养老金安排或计划。不同制度的给付方式会不同，单词本身不说明具体金额。旅游文章中的 a small pension 则可能是一家小旅店。','receive a pension；a pension fund；a pension scheme；stay in a pension。','salary 是工作期间的工资，pension 常与退休或过去服务相关。boarding-house 义不能按日常 /ˈpenʃən/ 的退休金直接翻译。',('She receives a pension after retiring from teaching.','她从教师岗位退休后领取养老金。'),('The booklet explains the pension scheme in plain language.','这本小册子用通俗语言解释了养老金计划。'),('They stayed in a small family-run pension near the lake.','他们住在湖边一家家庭经营的小旅馆。'),sources=[S('pension'),K('pension'),O('pension1_1'),O('pension2'),'https://www.gov.uk/plan-retirement-income']),
E('pensioner','英 /ˈpenʃənə/；美 /ˈpenʃənər/','领取养老金的人；退休人员','关注的不是“年龄看起来老”，而是这个人正在领取养老金或退休金。','经盎格鲁法语 pensionner、古法语 pensionnier，来自中世纪拉丁 pensionarius，接 pension 的付款词族。现代看似 pension + -er，但有独立的法语借入路线。',[['拉丁 pensio／pensionem','付款、固定给付'],['中世纪拉丁 pensionarius → 法语 pensionnier／pensionner','领取固定给付的人'],['英语 pensioner','领取养老金者；英式日常常用来指退休老人']],'英国日常语境中 pensioner 常指退休老人；严格说重点在领取养老金，未必所有老年人或所有退休者的情况都相同。','a retired pensioner；a pensioner on a fixed income；a pensioners’ association。','retiree 强调已经退休；pensioner 强调养老金领取身份。elderly person 只说年龄较大。',('The interview focused on a pensioner who volunteers at the library.','访谈聚焦于一位在图书馆做志愿服务的退休金领取者。'),('The local group offers computer classes for pensioners.','当地团体为退休人员开设电脑课程。'),sources=[S('pensioner'),K('pensioner'),O('pensioner')]),
E('pensionable','英、美 /ˈpenʃənəbəl/','可享养老金的；可计入养老金计算的','把某个年龄、职位或收入放到养老金规则里看：它是否属于有资格领取或可用于计算的那一部分。','英语 pension + -able。与可享养老金、可计入养老金有关，不是“这笔钱已经发下来”。',P+[['英语 pension + -able → pensionable','符合养老金资格或计算条件的']],'pensionable age 是达到养老金资格的年龄；pensionable pay 是计算养老金时纳入的薪酬。具体制度怎样规定，要看相应计划，这个词只指出关联。','pensionable age；pensionable earnings；pensionable service；pensionable pay。','pensionable 描写资格或计算范围；pension 是给付或制度名称。不要把 pensionable salary 直接译为已经领取的养老金。',('The statement separates pensionable pay from other allowances.','这份说明把可计入养老金计算的薪酬与其他津贴分开列出。'),('The handbook explains how pensionable service is recorded.','手册解释了可计入养老金的服务年限如何记录。'),sources=[K('pensionable'),O('pensionable'),S('pension')]),
E('spend','英、美 /spend/','花钱；花时间；耗费精力；度过','把手里的钱、时间或精力用到某件事上，用掉以后就不能把同一份资源再用一次。','英语继承古英语 -spendan，它本身曾借自拉丁 spendere 一类短化形式；可接 expendere，也有 dispendere 的来源分析，中古英语又可能与法语 despendre 合流。不是现代英文 expend 简单去掉 ex- 才成为 spend。',SP,'spend money on something 是花钱买某物；spend time doing something 是花时间做事。spend the weekend at home 是在家度过周末。过去式和过去分词是 spent。','spend money on；spend time doing；spend a day with；spend energy on。','cost 常以东西为主语，The book costs ten dollars；spend 常以花费者为主语，I spent ten dollars on it。不要说 spend time to do 代替通常的 doing 结构。',('I spent the afternoon sorting old photographs.','我花了一下午整理旧照片。'),('She spends very little on clothes.','她在衣服上花的钱很少。'),sources=[S('spend'),K('spend'),O('spend')]),
E('spent','英、美 /spent/','花了；已用掉的；精疲力竭的','钱已经花出，时间已经过去，或者人的力气已经消耗得差不多了。','spend 的不规则过去式、过去分词；也发展出形容词“耗尽的”。末尾是 /t/，不是给 spend 加一个可读出的 -ed。',SP+[['英语 spend → spent','花费已经发生；由已耗费引申为耗尽、疲惫']],'money spent 是花出去的钱；a spent battery 是电量耗尽的电池；feel spent 是感到精疲力竭。spent 不只是花钱，还能形容精力状态。','time well spent；money spent on；feel completely spent；a spent force。','tired 是累了；spent 往往强调力气几乎用尽。time spent 不一定是 time wasted，花了时间也可能很值得。',('The time we spent practising was worth it.','我们花在练习上的时间很值得。'),('After the long hike, I felt completely spent.','长途徒步后，我感到精疲力竭。'),sources=[S('spent'),K('spent'),O('spent')]),
E('spending','英、美 /ˈspendɪŋ/','支出；花费；正在花费','把花出去的钱汇总成一项活动或数字：家庭支出、政府支出、旅行花费。','英语 spend + -ing；既作动词形式，也作表示开支的名词。它承接花费义，不是另从拉丁直接借来的名词。',SP+[['英语 spend + -ing → spending','花费动作；作为名词指支出']],'government spending 是政府支出；spending on transport 是交通方面的花费。名词通常不可数，说一项项具体报销费用时更常用 expenses。','public spending；consumer spending；spending on housing；cut spending。','spending 是支出活动或总量，budget 是预算安排；两者可以不一致。spent 是已花费的过去式或分词。',('We recorded our spending for a month.','我们记录了一个月的支出。'),('The survey compares household spending on transport and food.','调查比较了家庭在交通和食品方面的支出。'),sources=[K('spending'),S('spend'),O('spending')]),
E('spender','英 /ˈspendə/；美 /ˈspendər/','花钱的人；某种消费习惯的人','把花钱的习惯贴到人身上：有人出手大，有人花钱很谨慎。','英语继承中古英语 spendere，对应 spend + -er“做这个动作的人”。现代的 spender 不是一种固定好坏评价，要看前面形容词。',SP+[['中古英语 spendere → spender','spend 与表示行动者的 -er 结合']],'a big spender 是花钱大方或花费很多的人；a careful spender 是谨慎花钱的人。单独 spender 只告诉你在谈消费者。','a big spender；a careful spender；a heavy spender；a modest spender。','spender 中性地说花钱的人；spendthrift 明确批评挥霍。big spender 可以出于慷慨，也可能出于浪费。',('He is a careful spender who compares prices before buying.','他花钱谨慎，买东西前会比较价格。'),('The hotel hopes to attract big spenders.','这家酒店希望吸引消费额高的客人。'),sources=[K('spender'),S('spend'),O('spender')]),
E('overspend','英 /ˌəʊvəˈspend/；美 /ˌoʊvərˈspend/','超支；花费过多','钱花过了计划线，或者明显超过了必要程度。','英语 over-“过度”+ spend，早期还有耗尽的用法；现代常指花钱太多。过去式、过去分词是 overspent，保留 spend→spent 的变化。',SP+[['英语 over- + spend → overspend','过度耗用 → 花费超过限度或需要']],'overspend on decorations 是在装饰上花得太多；overspend the budget 是超过预算。这个“过”需要参照某个预算、限额或实际需要。','overspend on；overspend the budget；avoid overspending；have overspent。','spend 只说花费；overspend 增加了过量或越界的判断。它不等于买贵东西，有很多小额支出也可能超支。',('We overspent on the venue and had to simplify the decorations.','场地费用超了支，我们只好简化装饰。'),('It is easy to overspend when every small purchase feels insignificant.','每笔小额购买都显得无足轻重时，很容易不知不觉花过头。'),sources=[S('overspend'),K('overspend'),O('overspend')]),
E('overspending','英 /ˌəʊvəˈspendɪŋ/；美 /ˌoʊvərˈspendɪŋ/','超支；过度花费','不是某次付款本身，而是整体花费已经超过合理范围或预定上限。','英语 overspend + -ing，表示超支行为或持续状态。over- 修饰整个 spend 动作，不是说“在某物上面花钱”。',SP+[['英语 over- + spend → overspend；再加 -ing','超过限度地花费 → 超支行为']],'overspending on a project 是项目花费超出计划。也可作进行时：We are overspending，表示我们现在花得太多。','overspending on advertising；control overspending；a pattern of overspending。','overspending 是花费过量；oversupply 是供给过量。两者都用 over-，对象和问题不同。',('The review found repeated overspending on travel.','审查发现差旅费用多次超支。'),('The chart makes the pattern of overspending easy to see.','这张图表让反复超支的情况一目了然。'),sources=[K('overspending'),S('overspend'),O('overspending')]),
E('spendthrift','英、美 /ˈspendθrɪft/','挥霍者；挥霍的','不是善于省钱，而是把积蓄、财富大手大脚花掉的人。这个词最容易被 thrift“节俭”的现代意思误导。','英语 spend + thrift；这里 thrift 用较旧的“财富、积蓄、收益”义。合起来是把财富花掉的人，并非一边花钱一边节俭。',SP+[['英语 spend + thrift〔旧义财富、积蓄〕→ spendthrift','把家底花掉的人；后也作形容词']],'a spendthrift 带批评，表示花钱缺乏节制。a spendthrift lifestyle 是挥霍的生活方式，和 thrifty“节俭的”正好形成鲜明对比。','a reckless spendthrift；a spendthrift lifestyle；a reputation as a spendthrift。','thrifty 是节俭，spendthrift 是挥霍。不要根据词尾里有 thrift 就把整个词当成赞美。',('The character begins as a spendthrift and ends the novel deeply in debt.','这个人物起初挥霍无度，小说结尾时已负债累累。'),('Her family worried about his spendthrift habits.','她的家人担心他挥霍无度的习惯。'),sources=[S('spendthrift'),K('spendthrift'),O('spendthrift_1')]),
]
